import pandas as pd
import numpy as np

train = pd.read_csv('train.csv')
test = pd.read_csv('test.csv')
feature_cols = [c for c in train.columns if c != 'target']
X_train = train[feature_cols].values
y_train = train['target'].values
X_test = test[feature_cols].values
y_test = test['target'].values

def gini(y):
    if len(y) == 0: return 0
    p = y.mean()
    return 2 * p * (1 - p)

def best_split(X, y, max_depth=3, min_samples=5):
    if max_depth == 0 or len(y) <= min_samples or len(np.unique(y)) == 1:
        return int(np.round(y.mean()))

    best_gain = -1
    best_feat = None
    best_thresh = None
    parent_gini = gini(y)

    for j in range(X.shape[1]):
        vals = np.sort(np.unique(X[:, j]))
        thresholds = (vals[:-1] + vals[1:]) / 2
        for t in thresholds[::max(1, len(thresholds)//20)]:  # subsample thresholds
            left = y[X[:, j] <= t]
            right = y[X[:, j] > t]
            if len(left) < min_samples or len(right) < min_samples:
                continue
            gain = parent_gini - (len(left)*gini(left) + len(right)*gini(right)) / len(y)
            if gain > best_gain:
                best_gain = gain
                best_feat = j
                best_thresh = t

    if best_feat is None:
        return int(np.round(y.mean()))

    left_mask = X[:, best_feat] <= best_thresh
    right_mask = ~left_mask
    left_tree = best_split(X[left_mask], y[left_mask], max_depth-1, min_samples)
    right_tree = best_split(X[right_mask], y[right_mask], max_depth-1, min_samples)
    return (best_feat, best_thresh, left_tree, right_tree)

def tree_predict(tree, x):
    if isinstance(tree, (int, np.integer)):
        return int(tree)
    feat, thresh, left, right = tree
    if x[feat] <= thresh:
        return tree_predict(left, x)
    return tree_predict(right, x)

# Try different depths and min_samples
for depth in [1, 2, 3, 4]:
    for ms in [3, 5, 8, 10]:
        tree = best_split(X_train, y_train, max_depth=depth, min_samples=ms)
        preds = [tree_predict(tree, x) for x in X_test]
        acc = np.mean(np.array(preds) == y_test)

        # LOO
        correct = 0
        for i in range(len(X_train)):
            mask = np.ones(len(X_train), dtype=bool)
            mask[i] = False
            t = best_split(X_train[mask], y_train[mask], max_depth=depth, min_samples=ms)
            if tree_predict(t, X_train[i]) == y_train[i]:
                correct += 1
        loo = correct / len(X_train)
        print(f'depth={depth} ms={ms:2d}: LOO={loo:.4f} test={acc:.4f}')
"

